export function evaluate({ inputs, time }) {
 const u = inputs.launchSpeed, g = inputs.gravity, m = inputs.mass;
 const T = 2 * u / g, ta = u / g;
 const t = Math.max(0, Math.min(time, T));
 const v = u - g * t, y = Math.max(0, u * t - g * t * t / 2);
 const F = m * g;
 let st = 'Rising';
 if (t <= 0) st = 'Ready to toss'; else if (t >= T - 1e-9) st = 'Back at launch height'; else if (Math.abs(t - ta) < 0.005) st = 'At the top'; else if (t > ta) st = 'Falling';
 const o = [];
 o.push(...sdk.panel({id:'lane.motion',x:10,y:34,w:300,h:376,title:'The motion',state:st}));
 o.push(...sdk.panel({id:'lane.graph',x:320,y:34,w:310,h:376,title:'Velocity over time',state:''}));
 o.push(sdk.axis('axis.h',{x:70,y:385,length:300,orientation:'y',min:0,max:2.2,ticks:[0,1,2],label:'Height',unit:'m'}));
 const py = h => 385 - h / 2.2 * 300;
 const by = py(y);
 o.push(sdk.circle('ball.toss', 130, by, 26));
 o.push(...sdk.vector('vec.v', {x:130,y:by-16}, {value:v,direction:'up'}, {scale:12,label:'v',role:'input'}));
 o.push(...sdk.vector('vec.a', {x:160,y:by}, {value:-g,direction:'up'}, {scale:4,label:'a',role:'warning'}));
 o.push(...sdk.callout(190,150,['v = '+sdk.format(v,2)+' m/s','a = '+sdk.format(-g,1)+' m/s^2','Fg = '+sdk.format(F,2)+' N'],{id:'callout.toss'}));
 const pts = sdk.sample(s => [s, u - g * s], 0, T, 20).map(p => ({x:p[0]*1,y:p[1]}));
 const cur = [];
 for (let i = 0; i <= 20; i++) { const s = t * i / 20; cur.push({x:s, y:u - g * s}); }
 o.push(sdk.plot('plot.vt',{x:370,y:60,w:250,h:280,axes:{x:{label:'t',min:0,max:1.8,unit:'s'},y:{label:'v',min:-5.5,max:5.5,unit:'m/s'}},series:[{label:'v = u - g t',kind:'line',points:pts.map(p=>({x:Math.min(1.8,p.x),y:p.y}))},{label:'so far',kind:'line',points:cur.map(p=>({x:Math.min(1.8,p.x),y:p.y}))}]}));
 o.push(sdk.text('plot.vt.note',500,372,'slope a = -g = '+sdk.format(-g,1),{align:'middle',role:'warning'}));
 return { frame:{width:640,height:420,objects:o,readouts:[{id:'velocity',value:v},{id:'acceleration',value:-g},{id:'force',value:F},{id:'motionState',value:st}]}, quantities:{launchSpeed:u,gravity:g,mass:m,apexTime:ta,apexHeight:u*u/(2*g),height:y,velocity:v,acceleration:-g,force:F} };
}
